//
// A tiny proxy in front of the Hosting emulator, started by start.mjs on the address the app is opened at (firebase.json's emulators.hosting.port);
// the emulator itself runs a few thousand ports higher (dev-config.mjs). It exists for one reason: the Hosting emulator ignores the "headers" of
// firebase.json, so it sends no Cache-Control at all, and a browser then keeps every file it has seen for a long time (a share of the file's age
// since it last changed). After a change, or after another project that used the same address, the page runs old scripts against new ones: errors such as
// "the requested module does not provide an export named ..." that no reload of the page itself fixes. Every response here is "Cache-Control: no-store",
// without the validators that invite caching, so what the browser runs is always what is on disk.
import http from "node:http";

/** The headers of a hosting response, changed so a browser never keeps it. */
export function noStoreHeaders(headers) {
  const next = { ...headers };
  delete next.etag;
  delete next["last-modified"];
  delete next["cache-control"];
  next["cache-control"] = "no-store";
  return next;
}

/**
 * Listens on `port` (host `host`) and forwards every request to the emulator on `targetPort`. Until the emulator is up it answers 502 with a short
 * explanation, so the page shows "starting" instead of a refused connection. Returns the server (close() it to stop).
 */
export function startDevProxy({ host = "127.0.0.1", port, targetPort }) {
  const server = http.createServer((req, res) => {
    const upstream = http.request({ host, port: targetPort, method: req.method, path: req.url, headers: { ...req.headers, host: `${host}:${targetPort}` }, agent: false }, (answer) => {
      res.writeHead(answer.statusCode || 502, noStoreHeaders(answer.headers));
      answer.pipe(res);
    });
    upstream.on("error", () => {
      if (!res.headersSent) res.writeHead(502, { "content-type": "text/plain; charset=utf-8", "cache-control": "no-store" });
      res.end("The hosting emulator is not up yet: try again in a moment.");
    });
    req.pipe(upstream);
  });
  server.listen(port, host);
  return server;
}
